pm.test("Status code is 200", () => {
  pm.response.to.have.status(200);
});

pm.test("Response has carts array with pagination fields", () => {
  const json = pm.response.json();
  pm.expect(json).to.have.property("carts").that.is.an("array");
  pm.expect(json).to.have.property("total");
  pm.expect(json).to.have.property("skip");
  pm.expect(json).to.have.property("limit");
});


pm.test("Cart object has expected schema", () => {
  const json = pm.response.json();
  const schema = {
    type: "object",
    required: ["id", "products", "total", "discountedTotal", "userId", "totalProducts", "totalQuantity"],
    properties: {
      id: { type: "number" },
      products: { type: "array" },
      total: { type: "number" },
      discountedTotal: { type: "number" },
      userId: { type: "number" },
      totalProducts: { type: "number" },
      totalQuantity: { type: "number" }
    }
  };
  const valid = tv4.validate(json.carts[0], schema);
  pm.expect(valid, JSON.stringify(tv4.error)).to.be.true;
});

pm.test("Product items have required fields", () => {
  const json = pm.response.json();
  json.carts[0].products.forEach(p => {
    pm.expect(p).to.have.all.keys(
      "id", "title", "price", "quantity", "total",
      "discountPercentage", "discountedTotal", "thumbnail"
    );
  });
});

pm.test("Response time is below 2000ms", () => {
  console.log("Actual response time (ms):", pm.response.responseTime);
  pm.expect(pm.response.responseTime).to.be.below(2000);
});

// Chain the cart id forward in case another request in the suite needs it
if (pm.response.json().carts.length > 0) {
  pm.collectionVariables.set("cartId", pm.response.json().carts[0].id);
}

